// Energy Compass YAML builder. Substitutes validated values for the tokens in
// templates.js (generated by tools/build_builder.py); it holds no generator logic.
(function () {
  'use strict';

  const TEXT = {
    en: {
      intro: 'Pick a section, enter your entity IDs and copy the YAML. Dashboard sections go into a Sections view (Edit dashboard → ⋮ → Raw configuration editor); the package goes into config/packages/.',
      lang: 'Language', section: 'Section', copy: 'Copy', copied: 'Copied.',
      invalid: 'Fix the highlighted fields.',
      note: 'The ApexCharts sections need ApexCharts Card 2.2.3 or later. The package prefix must match your Solarman TOU program entities, e.g. number.<prefix>1_power.',
    },
    pl: {
      intro: 'Wybierz sekcję, wpisz identyfikatory swoich encji i skopiuj YAML. Sekcje dashboardu wklej do widoku Sections (Edytuj dashboard → ⋮ → Edytor surowej konfiguracji); pakiet trafia do config/packages/.',
      lang: 'Język', section: 'Sekcja', copy: 'Kopiuj', copied: 'Skopiowano.',
      invalid: 'Popraw zaznaczone pola.',
      note: 'Sekcje ApexCharts wymagają ApexCharts Card 2.2.3 lub nowszej. Prefiks pakietu musi pasować do encji programów TOU z Solarman, np. number.<prefiks>1_power.',
    },
  };

  function fill(data, template, values) {
    let out = template;
    for (const [role, value] of Object.entries(values)) {
      const field = data.fields[role];
      if (!new RegExp(data.patterns[field.kind]).test(value)) throw new Error(role);
      out = out.split(field.token).join(value);
    }
    return out;
  }

  if (typeof document === 'undefined') {
    if (typeof module !== 'undefined') module.exports = { fill };
    return;
  }

  const data = window.EC_BUILDER;
  const $ = (id) => document.getElementById(id);
  const values = {};

  function render() {
    const lang = $('lang').value;
    const section = $('section').value;
    const t = TEXT[lang];
    const template = data.templates[section][lang];
    $('intro').textContent = t.intro;
    $('note').textContent = t.note;
    $('lang-label').textContent = t.lang;
    $('section-label').textContent = t.section;
    $('copy').textContent = t.copy;
    $('copied').textContent = '';
    for (const option of $('section').options) option.textContent = data.sections[option.value].label[lang];

    const fields = $('fields');
    fields.replaceChildren();
    const current = {};
    let valid = true;
    for (const role of template.fields) {
      const field = data.fields[role];
      const value = values[role] ?? field.example;
      const ok = new RegExp(data.patterns[field.kind]).test(value);
      valid = valid && ok;
      current[role] = value;
      const label = document.createElement('label');
      const name = document.createElement('span');
      name.textContent = field.label[lang];
      const input = document.createElement('input');
      input.value = value;
      input.placeholder = field.example;
      input.setAttribute('aria-invalid', String(!ok));
      input.addEventListener('change', () => { values[role] = input.value.trim(); render(); });
      label.append(name, input);
      fields.append(label);
    }
    $('error').textContent = valid ? '' : t.invalid;
    $('output').value = valid ? fill(data, template.yaml, current) : '';
  }

  for (const name of Object.keys(data.sections)) {
    const option = document.createElement('option');
    option.value = name;
    $('section').append(option);
  }
  if ((navigator.language || '').toLowerCase().startsWith('pl')) $('lang').value = 'pl';
  $('lang').addEventListener('change', render);
  $('section').addEventListener('change', render);
  $('copy').addEventListener('click', async () => {
    await navigator.clipboard.writeText($('output').value);
    $('copied').textContent = TEXT[$('lang').value].copied;
  });
  render();
})();
